import {transform,block,visit,dryRunMain} from './layout-repair-common-20261004.mjs';
export const TARGETS={'rates-v1':['p36-example-group','p56-example-block','p57-related-rates-drip-row','p57-related-rates-coffee-fuel-row'],'earning-money-v1':['p13-pay-example-group','p26-example-block','p27-example-header','p50-example-block','p61-example-block'],'operations-fractions-decimals-v1':['p28-q4'],'length-v1':['p45-diameter-turn-block'],'area-circles-sectors-v1':['p23-radius-example-group'],'solve-2-step-equations-v1':['p59-example-group','p60-teaching']};
export const PROJECTS=Object.keys(TARGETS);
export function repairResponseLabels(source){return transform(source,'response-labels',p=>{for(const id of TARGETS[p.id]??[]){const b=block(p,id);if(!b?.content?.children)continue;const nodes=[];visit(b.content,n=>{if(['part','question','group'].includes(n.type))nodes.push(n);});b.sourceReview??={};b.sourceReview.responses??=[];b.presentation={...b.presentation,sourceResponseLabels:true};for(const n of nodes){const numeric=p.id==='length-v1'&&/^p45-diameter-turn-step/.test(n.id),rowLabel=p.id==='earning-money-v1'&&/^p50-[abc]-worked$/.test(n.id);if(!numeric&&!rowLabel)n.label='';let r=b.sourceReview.responses.find(x=>x.targetId===n.id);if(!r){r={targetId:n.id,kind:n.answerSpaceMm>0?'working':'none'};b.sourceReview.responses.push(r);}r.label=numeric||rowLabel?n.label:'';}
 }});}
await dryRunMain(import.meta.url,repairResponseLabels,PROJECTS);
